import { apiClient, unwrap } from '../api';
import type { BffResponse } from '../api';
import type { AttendanceDto, AttendancePagedResult } from './responseModel';
import type { CreateAttendanceRequest, UpdateAttendanceRequest } from './requestModel';

/** Relative to VITE_API_URL (already includes /api/v1 or web-bff/api/v1). */
const BASE = '/patrol/attendance-logs';

type PagedEnvelope = {
  items?: AttendanceDto[];
  totalCount?: number;
  page?: number;
  pageSize?: number;
  totalPages?: number;
};

function normalizePaged(
  raw: PagedEnvelope | AttendanceDto[] | null | undefined,
): AttendancePagedResult {
  if (Array.isArray(raw)) {
    return {
      items: raw,
      totalCount: raw.length,
      page: 1,
      pageSize: raw.length || 50,
      totalPages: 1,
    };
  }
  const items = raw?.items ?? [];
  const totalCount = raw?.totalCount ?? items.length;
  const page = raw?.page ?? 1;
  const pageSize = raw?.pageSize ?? 50;
  const totalPages =
    raw?.totalPages ?? Math.max(1, Math.ceil(totalCount / Math.max(pageSize, 1)));
  return { items, totalCount, page, pageSize, totalPages };
}

export const attendanceEndpoint = {
  getList: async (params?: {
    search?: string;
    status?: string;
    route?: string;
    onlyOutZone?: boolean;
    page?: number;
    pageSize?: number;
  }) => {
    const qs = new URLSearchParams();
    if (params?.search) qs.set('search', params.search);
    if (params?.status) qs.set('status', params.status);
    if (params?.route) qs.set('route', params.route);
    if (params?.onlyOutZone) qs.set('onlyOutZone', 'true');
    qs.set('page', String(params?.page ?? 1));
    qs.set('pageSize', String(params?.pageSize ?? 50));
    const res = await apiClient.get<BffResponse<PagedEnvelope | AttendanceDto[]>>(
      `${BASE}?${qs}`,
    );
    return normalizePaged(unwrap(res));
  },

  getById: async (id: string) => {
    const res = await apiClient.get<BffResponse<AttendanceDto>>(`${BASE}/${id}`);
    return unwrap(res);
  },

  create: async (data: CreateAttendanceRequest) => {
    const res = await apiClient.post<BffResponse<AttendanceDto>>(BASE, data);
    return unwrap(res);
  },

  update: async (id: string, data: UpdateAttendanceRequest) => {
    const res = await apiClient.put<BffResponse<AttendanceDto>>(`${BASE}/${id}`, data);
    return unwrap(res);
  },

  delete: async (id: string): Promise<void> => {
    await apiClient.delete(`${BASE}/${id}`);
  },
};
