import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useDispatch } from 'react-redux';
import { useSearchParams } from 'react-router-dom';
import {
  Button,
  Checkbox,
  DEFAULT_CATALOG_LIST_TABLE_CONFIG,
  ErpListHeaderFilters,
  LinCatalogDataGrid,
  LinCatalogHistoryModal,
  LinCatalogListPagination,
  LinCatalogRowActionMenu,
  LinCatalogUiSchemaEditorModal,
  LinListFilterField,
  LinPageLayout,
  SearchInput,
  SearchTextInput,
  Select,
  buildCatalogRowMenuItems,
  catalogListTableConfigFromSchema,
  dispatchAppToast,
  useCatalogHistoryModal,
  useErpListSelection,
  useServerPagedListLoading,
  type ErpListTableConfig,
} from '@linm-soft-org/linm-web-common-components';
import { useCatalogUiSchema } from '../../hooks/useCatalogUiSchema';
import { attendanceService } from '../../services/attendance/attendanceService';
import { attendanceListPermissions } from '../../services/attendance/permissions';
import type { AttendanceDto } from '../../services/attendance/responseModel';
import {
  lookupNameOnly,
  ROAD_ROUTE_LOOKUP_CONFIG,
  ROAD_ROUTE_SEED,
} from '../../services/attendance/lookups';
import { catalogUiSchemaService } from '../../services/catalogUiSchema/catalogUiSchemaService';
import {
  buildDynamicGridColumns,
  type UiListColumnBootstrap,
} from '../../utils/bootstrapCatalogUiSchema';
import { ATTENDANCE_STATUSES, formatGps } from '../../demo/attendanceStore';
import { AttendanceFormSlideout, type AttendanceFormMode } from './AttendanceFormSlideout';
import styles from './AttendanceListPage.module.css';
import { fromCatalogToolbar } from '../buildRmmsGenericToolbar';

const TEST_ID = 'rmms-attendance-list';
const PAGE_ID = 'attendance';
const CATALOG_KIND = 'attendance-logs';
const ROW_MENU_HINT_KEY = `${TEST_ID}-row-menu-hint-dismissed`;

function formatCheckIn(iso: string): string {
  if (!iso) return '—';
  try {
    return new Date(iso).toLocaleString('vi-VN');
  } catch {
    return iso;
  }
}

const AttendanceListPage: React.FC = () => {
  const dispatch = useDispatch();
  const catalogHistory = useCatalogHistoryModal();
  const [searchParams, setSearchParams] = useSearchParams();
  const perms = attendanceListPermissions();
  const { schema, reload: reloadSchema } = useCatalogUiSchema(CATALOG_KIND);

  const [searchDraft, setSearchDraft] = useState('');
  const [statusDraft, setStatusDraft] = useState('');
  const [routeDraft, setRouteDraft] = useState('');
  const [onlyOutZoneDraft, setOnlyOutZoneDraft] = useState(false);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [routeFilter, setRouteFilter] = useState('');
  const [onlyOutZone, setOnlyOutZone] = useState(false);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState<number>(50);
  const [items, setItems] = useState<AttendanceDto[]>([]);
  const [totalCount, setTotalCount] = useState(0);
  const [slideOpen, setSlideOpen] = useState(false);
  const [slideMode, setSlideMode] = useState<AttendanceFormMode>('create');
  const [editing, setEditing] = useState<AttendanceDto | null>(null);
  const [rowMenu, setRowMenu] = useState<{
    x: number;
    y: number;
    row: AttendanceDto;
  } | null>(null);
  const [configOpen, setConfigOpen] = useState(false);
  const [pendingDelete, setPendingDelete] = useState<AttendanceDto | null>(null);
  const [tableConfig, setTableConfig] = useState<ErpListTableConfig>(() => ({
    ...DEFAULT_CATALOG_LIST_TABLE_CONFIG,
    ...catalogListTableConfigFromSchema(undefined),
    resizable: true,
  }));

  useEffect(() => {
    if (!schema?.list) return;
    setTableConfig({
      ...DEFAULT_CATALOG_LIST_TABLE_CONFIG,
      ...catalogListTableConfigFromSchema(schema.list),
      resizable: true,
    });
  }, [schema]);

  const {
    showTableLoading,
    pageLoading,
    pulseSearch,
    setLoadingMode,
    beginFetch,
    endFetch,
  } = useServerPagedListLoading();

  const load = useCallback(() => {
    beginFetch();
    attendanceService
      .getList({
        search: search.trim() || undefined,
        status: statusFilter || undefined,
        route: routeFilter || undefined,
        onlyOutZone: onlyOutZone || undefined,
        page,
        pageSize,
      })
      .then((res) => {
        setItems(res.items);
        setTotalCount(res.totalCount);
      })
      .catch(() => {
        setItems([]);
        setTotalCount(0);
      })
      .finally(() => endFetch());
  }, [search, statusFilter, routeFilter, onlyOutZone, page, pageSize, beginFetch, endFetch]);

  useEffect(() => {
    let cancelled = false;
    const t = window.setTimeout(() => {
      if (!cancelled) load();
    }, 0);
    return () => {
      cancelled = true;
      window.clearTimeout(t);
    };
  }, [load]);

  useEffect(() => {
    const form = searchParams.get('form');
    if (!form) return;
    let cancelled = false;
    const run = async () => {
      if (form === 'create') {
        if (cancelled) return;
        setEditing(null);
        setSlideMode('create');
        setSlideOpen(true);
      } else if (
        (form === 'edit' || form === 'view' || form === 'copy') &&
        searchParams.get('id')
      ) {
        try {
          const row = await attendanceService.getById(searchParams.get('id')!);
          if (cancelled) return;
          setEditing(row);
          setSlideMode(form);
          setSlideOpen(true);
        } catch {
          /* ignore */
        }
      }
      setSearchParams({}, { replace: true });
    };
    void run();
    return () => {
      cancelled = true;
    };
  }, [searchParams, setSearchParams]);

  const listSelection = useErpListSelection<AttendanceDto>({
    rows: items,
    totalCount,
    page,
    pageSize,
    getRowId: (r) => r.id,
  });
  const { activeRow, selectActiveRow, clearSelection } = listSelection;

  const applyFilters = useCallback(
    (nextSearch: string, nextStatus: string, nextRoute: string, nextOutZone: boolean) => {
      pulseSearch(() => {
        setSearch(nextSearch.trim());
        setStatusFilter(nextStatus);
        setRouteFilter(nextRoute);
        setOnlyOutZone(nextOutZone);
        setPage(1);
      });
    },
    [pulseSearch],
  );

  const handleSearch = useCallback(() => {
    applyFilters(searchDraft, statusDraft, routeDraft, onlyOutZoneDraft);
  }, [applyFilters, searchDraft, statusDraft, routeDraft, onlyOutZoneDraft]);

  const handleStatusChange = useCallback(
    (value: string) => {
      setStatusDraft(value);
      applyFilters(searchDraft, value, routeDraft, onlyOutZoneDraft);
    },
    [applyFilters, searchDraft, routeDraft, onlyOutZoneDraft],
  );

  const handleRouteChange = useCallback(
    (value: string) => {
      setRouteDraft(value);
      applyFilters(searchDraft, statusDraft, value, onlyOutZoneDraft);
    },
    [applyFilters, searchDraft, statusDraft, onlyOutZoneDraft],
  );

  const handleOnlyOutZoneChange = useCallback(
    (checked: boolean) => {
      setOnlyOutZoneDraft(checked);
      applyFilters(searchDraft, statusDraft, routeDraft, checked);
    },
    [applyFilters, searchDraft, statusDraft, routeDraft],
  );

  const statusOptions = useMemo(
    () => [
      { value: '', label: 'Tất cả trạng thái' },
      ...ATTENDANCE_STATUSES.map((t) => ({ value: t, label: t })),
    ],
    [],
  );

  const openRow = useCallback(
    (row: AttendanceDto, mode: AttendanceFormMode) => {
      selectActiveRow(row);
      setEditing(row);
      setSlideMode(mode);
      setSlideOpen(true);
    },
    [selectActiveRow],
  );

  const openCreate = useCallback(() => {
    if (!perms.canCreate) return;
    setEditing(null);
    setSlideMode('create');
    setSlideOpen(true);
  }, [perms.canCreate]);

  const requestDelete = useCallback(
    (row: AttendanceDto) => {
      if (!perms.canDelete) {
        dispatchAppToast(dispatch, {
          message: 'Không có quyền xóa chấm công',
          type: 'warning',
        });
        return;
      }
      setPendingDelete(row);
    },
    [perms.canDelete, dispatch],
  );

  const confirmDelete = useCallback(async () => {
    const row = pendingDelete;
    if (!row) return;
    setPendingDelete(null);
    try {
      await attendanceService.delete(row.id);
      dispatchAppToast(dispatch, {
        message: 'Đã xóa bản ghi chấm công',
        type: 'success',
      });
      clearSelection();
      setLoadingMode('filter');
      load();
    } catch (err) {
      dispatchAppToast(dispatch, {
        message: err instanceof Error ? err.message : 'Xóa chấm công thất bại',
        type: 'error',
      });
    }
  }, [pendingDelete, dispatch, clearSelection, setLoadingMode, load]);

  const reloadAll = useCallback(() => {
    setLoadingMode('filter');
    load();
  }, [load, setLoadingMode]);

  const handlePageChange = useCallback((next: number) => {
    setPage(next);
  }, []);

  const handlePageSizeChange = useCallback((next: number) => {
    setPageSize(next);
    setPage(1);
  }, []);

  const handleHistoryToolbar = useCallback(() => {
    if (!activeRow) {
      dispatchAppToast(dispatch, {
        message: 'Chọn một dòng (menu dòng) rồi mở Lịch sử.',
        type: 'info',
      });
      return;
    }
    catalogHistory.openHistory({
      documentType: PAGE_ID,
      documentId: activeRow.id,
      documentCode: activeRow.code,
    });
  }, [activeRow, catalogHistory.openHistory, dispatch]);

  const openConfig = useCallback(() => {
    setConfigOpen(true);
  }, []);

  const catalogToolbar = useMemo(
    () => ({
      testIdPrefix: TEST_ID,
      onRefresh: reloadAll,
      canAdd: perms.canCreate,
      onAdd: openCreate,
      canHistory: true,
      onHistory: handleHistoryToolbar,
      showSchemaConfig: true,
      onEditConfig: openConfig,
      showEdit: Boolean(activeRow && perms.canUpdate),
      showView: Boolean(activeRow && perms.canRead),
      onEdit: activeRow ? () => openRow(activeRow, 'edit') : undefined,
      onView: activeRow ? () => openRow(activeRow, 'view') : undefined,
      canDelete: Boolean(activeRow && perms.canDelete),
      onDelete: activeRow
        ? () => {
            requestDelete(activeRow);
          }
        : undefined,
    }),
    [
      reloadAll,
      perms.canCreate,
      perms.canUpdate,
      perms.canRead,
      perms.canDelete,
      openCreate,
      handleHistoryToolbar,
      openConfig,
      activeRow,
      openRow,
      requestDelete,
    ],
  );

  const listFilters = useMemo(
    () => (
      <ErpListHeaderFilters testIdPrefix={TEST_ID} filterCols={4}>
        <LinListFilterField testId={`${TEST_ID}-field-search`}>
          <SearchTextInput
            label="Tìm kiếm"
            placeholder="Mã / NV / tuyến / trạng thái / GPS…"
            value={searchDraft}
            onChange={setSearchDraft}
            onSearch={handleSearch}
            testId={`${TEST_ID}-search-text`}
          />
        </LinListFilterField>
        <LinListFilterField testId={`${TEST_ID}-field-status`}>
          <Select
            label="Trạng thái công"
            options={statusOptions}
            value={statusDraft}
            onChange={(e) => handleStatusChange(String(e.target.value))}
            data-testid={`${TEST_ID}-status-filter`}
            fullWidth
            size="small"
          />
        </LinListFilterField>
        <LinListFilterField testId={`${TEST_ID}-field-route`}>
          <SearchInput
            label="Tuyến đường"
            config={ROAD_ROUTE_LOOKUP_CONFIG}
            value={routeDraft}
            primaryDisplay={lookupNameOnly(ROAD_ROUTE_SEED, routeDraft)}
            showSecondaryInput={false}
            placeholder="Tất cả tuyến"
            onChange={(item) => handleRouteChange(item.value)}
            onClear={() => handleRouteChange('')}
          />
        </LinListFilterField>
        <LinListFilterField testId={`${TEST_ID}-field-only-out-zone`}>
          <Checkbox
            label="Chỉ lệch zone"
            checked={onlyOutZoneDraft}
            onChange={(e) => handleOnlyOutZoneChange(e.target.checked)}
            data-testid={`${TEST_ID}-only-out-zone`}
          />
        </LinListFilterField>
      </ErpListHeaderFilters>
    ),
    [
      searchDraft,
      statusDraft,
      routeDraft,
      onlyOutZoneDraft,
      handleSearch,
      handleStatusChange,
      handleRouteChange,
      handleOnlyOutZoneChange,
      statusOptions,
    ],
  );

  const uiColumns = useMemo<UiListColumnBootstrap<AttendanceDto>[]>(
    () => [
      {
        key: 'code',
        label: 'Mã chấm công',
        width: '140px',
        control: 'TEXT',
        allowSort: true,
        render: (row) => (
          <button
            type="button"
            className={styles.codeLink}
            onClick={() => openRow(row, 'view')}
            data-testid={`${TEST_ID}-code-${row.code}`}
          >
            {row.code}
          </button>
        ),
        getDisplayValue: (r) => r.code,
      },
      {
        key: 'userName',
        label: 'Nhân viên',
        width: '160px',
        control: 'TEXT',
        allowSort: true,
        render: (row) => row.userName,
        getDisplayValue: (r) => r.userName,
      },
      {
        key: 'route',
        label: 'Tuyến đường',
        width: '100px',
        control: 'LOOKUP',
        allowSort: true,
        render: (row) => row.route,
        getDisplayValue: (r) => r.route,
      },
      {
        key: 'checkInAt',
        label: 'Thời điểm',
        width: '160px',
        control: 'DATE',
        allowSort: true,
        render: (row) => formatCheckIn(row.checkInAt),
        getDisplayValue: (r) => r.checkInAt,
      },
      {
        key: 'kmPoint',
        label: 'Lý trình',
        width: '110px',
        control: 'TEXT',
        render: (row) => row.kmPoint || '—',
        getDisplayValue: (r) => r.kmPoint || '',
      },
      {
        key: 'inZone',
        label: 'InZone',
        width: '90px',
        control: 'SELECT',
        allowSort: true,
        render: (row) => (
          <span className={row.inZone ? styles.inZoneOk : styles.inZoneBad}>
            {row.inZone ? 'Trong zone' : 'Ngoài zone'}
          </span>
        ),
        getDisplayValue: (r) => (r.inZone ? 'Trong zone' : 'Ngoài zone'),
      },
      {
        key: 'status',
        label: 'Trạng thái',
        width: '120px',
        control: 'SELECT',
        allowSort: true,
        render: (row) => row.status,
        getDisplayValue: (r) => r.status,
      },
      {
        key: 'gps',
        label: 'GPS',
        width: '160px',
        control: 'TEXT',
        render: (row) => formatGps(row.lat, row.lng),
        getDisplayValue: (r) => formatGps(r.lat, r.lng),
      },
    ],
    [openRow],
  );

  const gridColumns = useMemo(
    () => buildDynamicGridColumns(schema, uiColumns),
    [schema, uiColumns],
  );

  const rowMenuItems = useMemo(
    () =>
      buildCatalogRowMenuItems({
        showView: perms.canRead,
        showEdit: perms.canUpdate,
        showCopy: perms.canCreate,
        showHistory: perms.canRead,
        showDelete: perms.canDelete,
      }),
    [perms.canRead, perms.canUpdate, perms.canCreate, perms.canDelete],
  );

  const handleRowMenuSelect = useCallback(
    (action: string) => {
      const row = rowMenu?.row;
      setRowMenu(null);
      if (!row) return;
      switch (action) {
        case 'view':
          openRow(row, 'view');
          break;
        case 'edit':
          openRow(row, 'edit');
          break;
        case 'copy':
          openRow(row, 'copy');
          break;
        case 'history':
          catalogHistory.openHistory({
            documentType: PAGE_ID,
            documentId: row.id,
            documentCode: row.code,
          });
          break;
        case 'delete':
          requestDelete(row);
          break;
        default:
          break;
      }
    },
    [rowMenu?.row, openRow, requestDelete, catalogHistory.openHistory],
  );

  const emptyMessage =
    search.trim() || statusFilter || routeFilter || onlyOutZone
      ? 'Không có bản ghi chấm công phù hợp bộ lọc.'
      : 'Không có dữ liệu chấm công.';

  return (
    <div
      className={styles.page}
      data-catalog-list-page
      data-testid={`${TEST_ID}-page`}
    >
      <LinPageLayout
        kind="catalog"
        filterBarLayout="standard"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        header={{
          title: 'Chấm công và định vị',
          titleIconClass: 'fas fa-user-clock',
          pageId: PAGE_ID,
        }}
        toolbar={fromCatalogToolbar(catalogToolbar)}
        listTitle="Sổ chấm công / check-in"
        listRowMenuHelp
        filters={listFilters}
        filtersTestId={`${TEST_ID}-filters`}
        showTableLoading={showTableLoading}
        pageLoading={pageLoading}
        skeletonRows={8}
        footer={
          <LinCatalogListPagination
            testIdPrefix={TEST_ID}
            page={page}
            pageSize={pageSize}
            totalCount={totalCount}
            onPageChange={handlePageChange}
            onPageSizeChange={handlePageSizeChange}
          />
        }
        modals={
          <>
            <AttendanceFormSlideout
              open={slideOpen}
              mode={slideMode}
              editing={editing}
              onClose={() => setSlideOpen(false)}
              onSaved={() => {
                setSlideOpen(false);
                setLoadingMode('filter');
                load();
              }}
              onModeChange={setSlideMode}
            />
            <LinCatalogRowActionMenu
              open={rowMenu != null}
              x={rowMenu?.x ?? 0}
              y={rowMenu?.y ?? 0}
              testIdPrefix={TEST_ID}
              onClose={() => setRowMenu(null)}
              onSelect={(action) => {
                handleRowMenuSelect(action);
              }}
              items={rowMenuItems}
            />
            <LinCatalogUiSchemaEditorModal
              isOpen={configOpen}
              onClose={() => setConfigOpen(false)}
              testIdPrefix={TEST_ID}
              catalogKind={CATALOG_KIND}
              loadSchema={catalogUiSchemaService.get}
              saveSchema={catalogUiSchemaService.save}
              onSaved={(next) => {
                setTableConfig({
                  ...DEFAULT_CATALOG_LIST_TABLE_CONFIG,
                  ...catalogListTableConfigFromSchema(next.list),
                  resizable: true,
                });
                reloadSchema();
                setConfigOpen(false);
              }}
              onError={(message) =>
                dispatchAppToast(dispatch, { message, type: 'error' })
              }
              onSuccess={(message) =>
                dispatchAppToast(dispatch, { message, type: 'success' })
              }
            />
            {catalogHistory.modalProps ? (
              <LinCatalogHistoryModal
                {...catalogHistory.modalProps}
                testIdPrefix={TEST_ID}
                onError={(message) =>
                  dispatchAppToast(dispatch, { message, type: 'error' })
                }
              />
            ) : null}
            {pendingDelete ? (
              <div className={styles.confirmOverlay} data-testid={`${TEST_ID}-confirm`}>
                <div className={styles.confirmCard} role="dialog" aria-modal="true">
                  <p>
                    Xóa bản ghi chấm công «{pendingDelete.code} — {pendingDelete.userName}»?
                  </p>
                  <div className={styles.confirmActions}>
                    <Button
                      variant="secondary"
                      size="sm"
                      onClick={() => setPendingDelete(null)}
                    >
                      Hủy
                    </Button>
                    <Button variant="primary" size="sm" onClick={() => void confirmDelete()}>
                      Xóa
                    </Button>
                  </div>
                </div>
              </div>
            ) : null}
          </>
        }
      >
        <div className={styles.gridWrap} data-testid={`${TEST_ID}-grid-wrap`}>
          <LinCatalogDataGrid
            testIdPrefix={TEST_ID}
            rows={items}
            page={page}
            pageSize={pageSize}
            columns={gridColumns}
            getRowId={(r) => r.id}
            selection={listSelection}
            tableConfig={tableConfig}
            paginateClient={false}
            empty={
              <div className={styles.empty} data-testid={`${TEST_ID}-empty`}>
                {emptyMessage}
              </div>
            }
            onRowOpenActionMenu={({ row, x, y }) => {
              selectActiveRow(row);
              setRowMenu({ row, x, y });
            }}
            onRowDoubleClick={(row) => openRow(row, 'view')}
            rowMenuHintDismissStorageKey={ROW_MENU_HINT_KEY}
          />
        </div>
      </LinPageLayout>
    </div>
  );
};

export default AttendanceListPage;
